/* 仅本机原型内容存储；正式上传由候选接口承接。 */
window.EamFiles=(()=>{let db;const scope=()=>{if(!Eam.s.fileScope){Eam.s.fileScope=crypto.randomUUID();Eam.save();}return Eam.s.fileScope;};const open=()=>db?Promise.resolve(db):new Promise((resolve,reject)=>{const r=indexedDB.open('eam-prototype-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('contents');r.onsuccess=()=>{db=r.result;resolve(db);};r.onerror=()=>reject(r.error);});
async function put(entries){const database=await open();return new Promise((resolve,reject)=>{const tx=database.transaction('contents','readwrite');for(const [id,blob]of entries)tx.objectStore('contents').put(blob,scope()+':'+id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function get(file){if(file.previewUrl){const r=await fetch(file.previewUrl);if(!r.ok)throw Error('示例内容不可用');return r.blob();}const database=await open();return new Promise((resolve,reject)=>{const r=database.transaction('contents').objectStore('contents').get(scope()+':'+(file.localContentKey||file.id));r.onsuccess=()=>r.result?resolve(r.result):reject(Error('本机没有文件内容，请重新选择文件；元数据不等于上传完成'));r.onerror=()=>reject(r.error);});}
async function remove(keys){const database=await open();return new Promise((resolve,reject)=>{const tx=database.transaction('contents','readwrite');for(const key of keys)tx.objectStore('contents').delete(scope()+':'+key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}return {put,get,remove};})();
